```python
class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def search(self, word: str) -> bool:
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end_of_word

    def _find_completions(self, node: TrieNode, prefix: str, completions: list) -> None:
        if len(completions) >= 3:
            return
        if node.is_end_of_word:
            completions.append(prefix)
        for char in sorted(node.children.keys()):
            self._find_completions(node.children[char], prefix + char, completions)

    def autocomplete(self, prefix: str) -> list:
        node = self.root
        for char in prefix:
            if char not in node.children:
                return []  # No completions if prefix not found
            node = node.children[char]
        completions = []
        self._find_completions(node, prefix, completions)
        return completions

# Example usage
