    trie = Trie()
    words = ["apple", "app", "apricot", "banana", "band", "bat", "batman"]

    for word in words:
        trie.insert(word)

    print(trie.search("app"))        # True
    print(trie.search("application")) # False
    print(trie.autocomplete("ap"))    # ['apple', 'app', 'apricot']
    print(trie.autocomplete("ban"))   # ['banana', 'band']
    print(trie.autocomplete("b"))     # ['banana', 'band', 'bat']
    print(trie.autocomplete("z"))     # []
```

