interface EventMap {
  [event: string]: any; // Event name mapped to the payload type
}

class EventEmitter<T extends EventMap> {
  // Private storage for events and their listeners
  private events: {
    [K in keyof T]?: Array<(payload: T[K]) => void>;
  } = {};

  // Method to subscribe to an event
  on<K extends keyof T>(event: K, listener: (payload: T[K]) => void): void {
    if (!this.events[event]) {
      this.events[event] = []; // Initialize the array if it doesn't exist
    }
    this.events[event]!.push(listener); // Push the listener to the array
  }

  // Method to unsubscribe from an event
  off<K extends keyof T>(event: K, listener: (payload: T[K]) => void): void {
    if (!this.events[event]) return; // No listeners for this event

    // Filter out the listener from the array
    this.events[event] = this.events[event]!.filter(l => l !== listener);
  }

  // Method to emit an event
  emit<K extends keyof T>(event: K, payload: T[K]): void {
    if (!this.events[event]) return; // No listeners for this event

    // Call all registered listeners with the payload
    this.events[event]!.forEach(listener => listener(payload));
  }
}

